using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace NyaForge.Mcp;

[McpServerToolType]
public sealed class ForgeTools(InstanceConnection connection)
{
    [McpServerTool(Name="forge_import_image"), Description("Import a local PNG as a new layer. Submit one layers.import operation in the explicit command envelope: layerContext, layerId GUID, name, canvas width/height, insertion index, absolute path, sourceHash (SHA256 of original PNG bytes), fit boolean. PNG <=16 MiB and 1024x1024, supported profiles only. Uses the app decoder and common fitting pipeline. Retrying requires the original file still available and matching hash; same decoded command is replay-safe. After uncertain delivery inspect layers/state. This tool reads the named local file; it does not upload it to a remote server.")]
    public Task<JsonElement> ImportImage(ApplyCommand command,CancellationToken cancellationToken)=>connection.RequestAsync("import_image",cancellationToken,command);
    [McpServerTool(Name="forge_faces_inspect"), Description("Read up to 64 polygon faces from a current node mesh input/output, pinned by documentId/revision/snapshotHash. Start offset=0, follow nextOffset until null. Face and corner IDs and vertex references are decimal strings; corners preserve winding and include UV or null. Triangle-only nodes reject with POLYGON_REQUIRED. No editing or stale preview fallback.")]
    public Task<JsonElement> InspectFaces(MeshPageQuery faces,CancellationToken cancellationToken)=>connection.RequestAsync("faces_inspect",cancellationToken,faces,"faces");
    [McpServerTool(Name="forge_vertices_inspect"), Description("Read up to 1024 vertices from a current node mesh input or output. Pin documentId/revision and mesh snapshotHash from graph inspection for every page. Use offset=0 initially and nextOffset until null. Returns restPosition and avatarPosition in meters. meshVertexIndex IDs are integers; polygonVertexId IDs are decimal strings preserving 64-bit precision. Does not edit or use stale preview geometry.")]
    public Task<JsonElement> InspectVertices(MeshPageQuery vertices,CancellationToken cancellationToken)=>connection.RequestAsync("vertices_inspect",cancellationToken,vertices,"vertices");
    [McpServerTool(Name="forge_validate"), Description("Run a read-only output budget check pinned by documentId and expectedRevision. Profile pc uses 70,000 triangles, 8 materials and 2048px textures; profile mobile uses 20,000 triangles, 1 material and 1024px textures. Returns pass/fail/unknown per check. Bone deformation and avatar fit remain unknown in this static profile; a pass is not a VRChat or human visual acceptance.")]
    public Task<JsonElement> Validate(ValidationCommand validation,CancellationToken cancellationToken)=>connection.RequestAsync("validate",cancellationToken,validation,"validation");
    [McpServerTool(Name="forge_export"), Description("Export current ready output through the supported NyaForge Bake profile preserving material/texture attributes. Use saveTarget.directory from state and a new GUID exportId. Writes under directory/exports/exportId. Existing output directories are rejected, including repeated requests; no automatic retry. Returns manifestPath and kind. Does not save native project or change document revision.")]
    public Task<JsonElement> ExportProject(ExportProjectCommand export,CancellationToken cancellationToken)=>connection.RequestAsync("export",cancellationToken,export,"export");
    [McpServerTool(Name="forge_save_project"), Description("Save native authoring data to the destination currently selected in the GUI. Read documentId/revision and saveTarget from forge_get_state first. Inspect result.success/code. A repeated save with an old save version returns SAVE_CONFLICT; re-read state after uncertain delivery. Does not discard or reopen the document.")]
    public Task<JsonElement> SaveProject(SaveProjectCommand save,CancellationToken cancellationToken)=>connection.RequestAsync("save_project",cancellationToken,save,"save");
    [McpServerTool(Name="forge_capture"), Description("Capture the final ready model from front, back, left, right and oblique at 256px. Returns five PNG image content blocks and matching immutable snapshot metrics/camera records. Does not edit or save the project. Empty, faceless or incomplete final output cannot be captured.")]
    public async Task<ModelContextProtocol.Protocol.CallToolResult> Capture(CancellationToken cancellationToken)=>CaptureResult.Convert(await connection.RequestAsync("capture",cancellationToken));
    [McpServerTool(Name="forge_secondary_motion_state"), Description("Read the current secondary-motion preview state. Returns whether the imported VRM spring data is available, format, playing state, fixed-step count and pending time. The simulation is transient and is never saved.")]
    public Task<JsonElement> SecondaryMotionState(CancellationToken cancellationToken)=>connection.RequestAsync("secondary_motion_state",cancellationToken);
    [McpServerTool(Name="forge_secondary_motion_play"), Description("Start or resume the shared secondary-motion preview for the currently imported VRM. This changes only the transient preview pose; it does not edit or save authoring data.")]
    public Task<JsonElement> SecondaryMotionPlay(CancellationToken cancellationToken)=>connection.RequestAsync("secondary_motion_play",cancellationToken);
    [McpServerTool(Name="forge_secondary_motion_pause"), Description("Pause the shared secondary-motion preview while retaining its transient pose and fixed-step count. It does not edit or save authoring data.")]
    public Task<JsonElement> SecondaryMotionPause(CancellationToken cancellationToken)=>connection.RequestAsync("secondary_motion_pause",cancellationToken);
    [McpServerTool(Name="forge_secondary_motion_reset"), Description("Stop secondary-motion preview and restore the authored pose/display. The transient simulation is discarded and no project data is changed.")]
    public Task<JsonElement> SecondaryMotionReset(CancellationToken cancellationToken)=>connection.RequestAsync("secondary_motion_reset",cancellationToken);
    [McpServerTool(Name="forge_secondary_motion_rebuild"), Description("Rebuild the secondary-motion preview from the current imported settings. A paused preview stays paused; the rebuilt state is transient and is not saved.")]
    public Task<JsonElement> SecondaryMotionRebuild(CancellationToken cancellationToken)=>connection.RequestAsync("secondary_motion_rebuild",cancellationToken);
    [McpServerTool(Name="forge_secondary_motion_step"), Description("Advance a paused secondary-motion preview by exactly one fixed 1/60-second step. If the preview is running it advances one step and remains running. The result is transient and is not saved.")]
    public Task<JsonElement> SecondaryMotionStep(CancellationToken cancellationToken)=>connection.RequestAsync("secondary_motion_step",cancellationToken);
    [McpServerTool(Name="forge_secondary_motion_capture"), Description("Capture a bounded transient secondary-motion run. frameCount 1..8, warmupSteps 0..120, width/height 32..512 with an 8*256*256 pixel budget. Returns inline PNG frames plus input/config hashes, adapter/package/Unity/build, fixed-step, pose/root/collider conditions and failure metadata. The native document and saved project are not changed; this is preview evidence, not VRChat acceptance.")]
    public async Task<ModelContextProtocol.Protocol.CallToolResult> SecondaryMotionCapture(SecondaryMotionCaptureCommand capture,CancellationToken cancellationToken)=>CaptureResult.Convert(await connection.RequestAsync("secondary_motion_capture",cancellationToken,capture,"capture"));
    [McpServerTool(Name="forge_apply"), Description("Apply an explicit revision-checked command. Also supports object.add_graph (newObjectId and explicit graph IDs/nodes/edges), graph.node.add/update (node), graph.node.remove and graph.output (nodeId). Layer drawing: layers.stroke takes layerContext/layerId/points/radius/color like paint.stroke. layers.mask.fill creates or replaces a uniform mask with width/height/target byte 0..255. layers.mask.stroke takes layerContext/layerId/points/radius/target byte/strength 0..1 and requires a mask. layers.mask.clear removes a mask. All require fresh layerContext. Layers: layers.migrate takes paintContext and explicit layerId GUID. Subsequent operations require layerContext from graph_inspect layerStack.context, refreshed after each change. layers.add creates transparent layer with layerId/name/width/height/index; dimensions must match canvas. layers.appearance takes layerId/opacity 0..1/visible boolean. layers.remove takes layerId, layers.move adds index, layers.rename adds name. Order is bottom-to-top. Paint: image.paint takes integer width/height and begins white; connect a polygon with UVs to mesh input, image output to baseColor. paint.stroke requires paintContext from graph_inspect, points as UV pairs 0..1, radius in pixels, color as sRGB RGBA integer bytes 0..255. Re-read context after every stroke. Node types: mesh.assign-materials takes slots integer array and one material input per slot. mesh.polygon-source requires domainId GUID, vertices (decimal string id, position xyz), faces (decimal string id, materialSlot, corners with decimal string id/vertexId), scale and translation xyz. No corner attributes in this creation profile. mesh.polygon-edit takes empty parameters. primitive.plane with width/height; mesh.edit and mesh.output with empty parameters; version 1. material.standard requires linear baseColor RGBA, metallic, roughness, emission RGB, alphaMode (Opaque/Cutout/Blend), alphaCutoff. mesh.assign-material takes empty parameters. Node update replaces its payload. graph.vertices.translate requires context from graph_inspect editContext, vertexIds and delta in rest space. Polygon creation: polygon.vertices.add takes context/position xyz; polygon.faces.create takes context/ordered elementIds perimeter/materialSlot. polygon.solidify takes context/thickness in rest units; polygon.uv.project takes context and uses the built-in projection. Newly allocated IDs must be read back from edit output. Polygon operations: polygon.vertices.translate and polygon.faces.extrude require context, elementIds (canonical decimal strings), delta xyz in rest space. polygon.faces.delete and polygon.faces.material require context and elementIds; faces.material also takes materialSlot. Read IDs from the polygon edit node output, and context from its editContext. Supported kinds: vertices.translate (static profile; vertexIds, delta xyz in rest space), graph.connect (fromNode/fromPort/toNode/toPort), graph.disconnect (nodeId/inputPort), history.undo, history.redo. Obtain identity, revision and editSourceHash from state. Preserve commandId and payload when retrying after uncertain delivery. Inspect success/code in the result.")]
    public Task<JsonElement> Apply(ApplyCommand command,CancellationToken cancellationToken)=>connection.RequestAsync("apply",cancellationToken,command);
    [McpServerTool(Name="forge_graph_inspect"), Description("Inspect the current bounded graph: node IDs and ports, connections, mesh identities, rest skeleton outputs, skin binding outputs, material values and diagnostics. Image output reports hashes and dimensions only. Does not return geometry payloads or edit the graph.")]
    public Task<JsonElement> InspectGraph(CancellationToken cancellationToken)=>connection.RequestAsync("graph_inspect",cancellationToken);
    [McpServerTool(Name="forge_capabilities"), Description("Read supported remote methods, local node definitions and limits from the selected application. Local node support does not imply remote editing support.")]
    public Task<JsonElement> Capabilities(CancellationToken cancellationToken)=>connection.RequestAsync("capabilities",cancellationToken);
    [McpServerTool(Name="forge_get_state"), Description("Read the explicitly selected NyaForge instance's current authoring state. Does not edit the document.")]
    public Task<JsonElement> GetState(CancellationToken cancellationToken)=>connection.RequestAsync("get_state",cancellationToken);
}








